import {setupNavigation} from './navigation.js';
import {certificates} from './certificates.js';
import {selectCertificates} from './selection.js';
const $=s=>document.querySelector(s);let category='All';let opener;
const categories=['All','Cisco','TESDA CSS','Microsoft','Seminars','Webinars'];
for(const name of categories){const b=document.createElement('button');b.textContent=`${name} (${name==='All'?certificates.length:certificates.filter(c=>c.category===name).length})`;b.setAttribute('aria-pressed',String(name==='All'));b.addEventListener('click',()=>{category=name;for(const el of $('#filters').children)el.setAttribute('aria-pressed',String(el===b));render();});$('#filters').append(b);}
const date=s=>new Date(s+'T12:00:00').toLocaleDateString('en',{day:'numeric',month:'short',year:'numeric'});
function render(){const results=selectCertificates(certificates,category,$('#search').value,$('#sort').value);$('#gallery').replaceChildren();$('#result-count').textContent=`${results.length} of ${certificates.length} learning records`;
for(const c of results){const card=document.createElement('article');card.className='certificate';card.innerHTML=`<button class="thumb" aria-label="Preview certificate"><img loading="lazy" width="900" height="650" alt=""></button><div class="cert-copy"><div class="cert-meta"><span></span><time></time></div><h3></h3><p class="issuer"></p><p class="type"></p><button class="view">View certificate <span>↗</span></button></div>`;card.querySelector('img').src=c.preview;card.querySelector('img').alt=c.title+(c.status==='pending'?' evaluation receipt preview':' certificate preview');card.querySelector('.thumb').setAttribute('aria-label','Preview '+c.title);card.querySelector('h3').textContent=c.title;card.querySelector('.cert-meta span').textContent=c.category.toUpperCase();card.querySelector('time').textContent=date(c.date);card.querySelector('time').dateTime=c.date;card.querySelector('.issuer').textContent=c.issuer;card.querySelector('.type').textContent=c.type;if(c.status==='pending')card.querySelector('.view').textContent='View screenshot ↗';for(const b of card.querySelectorAll('button'))b.addEventListener('click',()=>openCertificate(c,b));$('#gallery').append(card);}
if(!results.length){const p=document.createElement('p');p.className='empty';p.textContent='No certificates match your search. Try another topic or choose All.';$('#gallery').append(p);}}
function openCertificate(c,b){opener=b;$('#dialog-title').textContent=c.title;$('#dialog-category').textContent=c.category;$('#dialog-meta').textContent=`${c.issuer} · ${date(c.date)} · ${c.type}`;const img=new Image();img.src=/\.(jpg|png|webp)$/i.test(c.file)?c.file:c.preview;img.alt=c.title+(c.status==='pending'?' — evaluation receipt, certificate pending':' — original certificate');$('#document-view').replaceChildren(img);$('#open-file').href=c.file;$('#download-file').href=c.file;$('#download-file').download=c.title.replace(/[^a-z0-9]+/gi,'-')+c.file.slice(c.file.lastIndexOf('.'));$('#drive-file').hidden=!c.original;if(c.original)$('#drive-file').href=c.original;else $('#drive-file').removeAttribute('href');$('.preview-help').textContent=c.status==='pending'?'Temporary evaluation receipt screenshot. Certificate not yet received; the date shown is the receipt date.':'Showing the original document’s first page. Open the file for full resolution and all pages.';document.body.classList.add('modal-open');$('#certificate-dialog').showModal();$('#close-dialog').focus();}
$('#close-dialog').addEventListener('click',()=>$('#certificate-dialog').close());$('#certificate-dialog').addEventListener('close',()=>{document.body.classList.remove('modal-open');opener?.focus();});$('#certificate-dialog').addEventListener('click',e=>{if(e.target===$('#certificate-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#search').addEventListener('input',render);$('#sort').addEventListener('change',render);render();
const menu=$('.menu'),nav=$('#navigation');function closeMenu(){menu.setAttribute('aria-expanded','false');nav.classList.remove('open');}menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);});nav.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();menu.focus();}});window.matchMedia('(min-width: 761px)').addEventListener('change',e=>{if(e.matches)closeMenu();});
setupNavigation(nav);
